import React from "react";
import "./Blog.css";

const blogPosts = [
  {
    title: "Why Daily Coding Matters",
    summary: "Discover how small daily challenges build long-term mastery and confidence.",
    author: "Faiz Nagpurwala",
    date: "Nov 20, 2025",
  },
  {
    title: "Frontend vs Backend: Where to Start?",
    summary: "Explore the strengths of each path and how to choose based on your goals.",
    author: "Developer 2",
    date: "Nov 22, 2025",
  },
  {
    title: "DSA for Interviews: A Smart Strategy",
    summary: "Learn how to prepare for coding interviews with focused DSA practice.",
    author: "Developer 3",
    date: "Nov 24, 2025",
  },
];

export default function Blog() {
  return (
    <div className="blog-container" id="Blog">
      <h1 className="blog-title">DailyCode <span>Blog</span></h1>
      <p className="blog-subtext">Insights, strategies, and stories from our developer community.</p>

      <div className="blog-grid">
        {blogPosts.map((post, index) => (
          <div key={index} className="blog-card">
            <h2 className="blog-card-title">{post.title}</h2>
            <p className="blog-card-summary">{post.summary}</p>
            <div className="blog-meta">
              <span>{post.author}</span>
              <span>{post.date}</span>
            </div>
            <button className="blog-read-btn">Read More</button>
          </div>
        ))}
      </div>
    </div>
  );
}
